// Same120 authored operating/pose values through real owned host/Node/RA07/ring.
// Device-free sink only. No recorder/tap, microphone, endpoint or game calls.
using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Threading;using System.Web.Script.Serialization;
using RichAudio.Beacon.Transport;using RichAudio.Beacon.Windows;
internal static class TestLowLatencyActualChain {
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=4194304,RecursionLimit=32};static BatiPlaybackSession current;static long sequence;static string root;static int checks,cpuWorkers;static volatile bool cpuStop;static Thread[] loadThreads;static double loadResult;static bool armFailed;static readonly List<Process> affinityProcesses=new List<Process>();static readonly List<IntPtr> oldAffinities=new List<IntPtr>();static long contentionMask;
 static void StartLoad(){if(cpuWorkers>0){using(var self=Process.GetCurrentProcess()){long available=self.ProcessorAffinity.ToInt64();contentionMask=0;for(int i=0;i<63&&CountBits(contentionMask)<2;i++)if((available&(1L<<i))!=0)contentionMask|=1L<<i;}if(CountBits(contentionMask)<2)throw new InvalidOperationException("two owned-process cores required");foreach(int pid in new[]{Process.GetCurrentProcess().Id,current.HostPid,NodePid()}){var p=Process.GetProcessById(pid);affinityProcesses.Add(p);oldAffinities.Add(p.ProcessorAffinity);p.ProcessorAffinity=new IntPtr(contentionMask);}}cpuStop=false;loadThreads=new Thread[cpuWorkers];for(int n=0;n<loadThreads.Length;n++){loadThreads[n]=new Thread(delegate(){double v=1;while(!cpuStop)for(int i=1;i<=10000;i++)v=Math.Sqrt(v+i);loadResult=v;}){IsBackground=true,Name="RichAudio bounded fixture CPU contention"};loadThreads[n].Start();}}
 static void StopLoad(){cpuStop=true;if(loadThreads!=null)foreach(var t in loadThreads)if(t!=null&&!t.Join(3000))throw new TimeoutException("fixture CPU worker release");loadThreads=null;for(int i=affinityProcesses.Count-1;i>=0;i--){try{if(!affinityProcesses[i].HasExited)affinityProcesses[i].ProcessorAffinity=oldAffinities[i];}finally{affinityProcesses[i].Dispose();}}affinityProcesses.Clear();oldAffinities.Clear();GC.KeepAlive(loadResult);}
 static int CountBits(long mask){int count=0;for(int i=0;i<63;i++)if((mask&(1L<<i))!=0)count++;return count;}
 static int NodePid(){var h=Read(Path.Combine(root,".local","gameplay",current.Session,"host.json"));if(h==null)throw new InvalidOperationException("owned Node identity absent");return Convert.ToInt32(h["nodePid"]);}
 static void Need(bool yes,string why){checks++;if(!yes)throw new Exception(why);}
 static Dictionary<string,object> Read(string p){try{return Json.DeserializeObject(File.ReadAllText(p))as Dictionary<string,object>;}catch(IOException){return null;}catch(ArgumentException){return null;}}
 static void Feed(int i){long q=Stopwatch.GetTimestamp();double moving=i<40?0:(i-40)*.15;current.PublishAccepted(new GameplayFrame{Session=current.Session,ValidThroughTicks=q+Stopwatch.Frequency/5,
  Listener=new ListenerState{Version=1,Session=current.Session,Generation=1,Sequence=sequence++,ObservationTicks=q,ClockFrequency=Stopwatch.Frequency,GameTimeMs=sequence*50,Position=new[]{0d,0d,1d},Velocity=new[]{0d,0d,0d},Forward=new[]{0d,1d,0d},Up=new[]{0d,0d,1d},ListenerKind="camera",VelocityKind="estimated-camera-difference",Paused=false,Valid=true,Reason="valid",Coordinates="gta-native-unscaled",Units="native-unverified"},
  Vehicles=new[]{new GameplayVehicle{Id="low-latency-authored-bati",Generation=1,ObservationTicks=q,Model=0xf9300cc5u,Context="player",Position=new[]{2d,4d+moving,1d},Velocity=new[]{0d,i<40?0:3d,0d},Forward=new[]{0d,1d,0d},Up=new[]{0d,0d,1d},OperatingPoint=i<0?.2:.2+.7*(.5+.5*Math.Sin(i*.12)),Running=true,Valid=true}}},q+Stopwatch.Frequency/5);}
 static object Run(string candidate){root=candidate;sequence=0;var config=PlayableConfiguration.Load(Path.Combine(root,"playable.json"));string pointer=Path.Combine(root,".local","ll-fixture-"+Guid.NewGuid().ToString("N")+".json");File.WriteAllText(pointer,Json.Serialize(new{schema=1,packageRoot=root,manifestSha256=PlayableConfiguration.Digest(config.Manifest)}));current=new BatiPlaybackSession(Guid.NewGuid().ToString("N"),true,false,false);current.Start(pointer,config.GameExecutable);var timer=Stopwatch.StartNew();while(current.Configuration==null){if(timer.ElapsedMilliseconds>10000)throw new TimeoutException("configuration");Thread.Sleep(5);}Need(current.Enable(),"explicit device-free enable");string status=Path.Combine(root,".local","gameplay",current.Session,"host.json");timer.Restart();
  for(;;){Feed(-1);Thread.Sleep(25);var h=Read(status);if(h!=null&&Convert.ToDouble(h["sumSquares"])>0)break;if(timer.ElapsedMilliseconds>15000||h!=null&&Object.Equals(h["hostState"],"stopped"))throw new TimeoutException("source startup: "+(h==null?"no host status":Json.Serialize(h)));}
  double startupMs=timer.Elapsed.TotalMilliseconds;double cpuBefore=Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds;StartLoad();timer.Restart();for(int i=0;i<120;i++){while(timer.Elapsed.TotalMilliseconds<i*50)Thread.Sleep(1);Feed(i);}Thread.Sleep(25);StopLoad();double loadCpuMs=Process.GetCurrentProcess().TotalProcessorTime.TotalMilliseconds-cpuBefore;current.Disable();timer.Restart();while(current.HostPid!=0){if(timer.ElapsedMilliseconds>10000)throw new TimeoutException("fixture shutdown");Thread.Sleep(10);}current.Stop();Need(current.Join(10000),"owned session and expiry worker joined");var final=Read(status);Need(final!=null&&Object.Equals(final["hostState"],"stopped")&&final["failure"]==null,"clean closed host");Need(!(bool)final["endpointOpened"]&&!(bool)final["recordingRequested"]&&!(bool)final["loopbackRequested"],"no endpoint or new recording");Need(Convert.ToInt64(final["underflowFrames"])==0,"actual Node+ring has zero starvation");Need(Convert.ToDouble(final["sumSquares"])>0,"genuine private source material reaches production ring");Need(final.ContainsKey("offlineLatencyMeasurements"),"actual fixture timing metadata retained");var timing=final["offlineLatencyMeasurements"]as Dictionary<string,object>;Need(timing!=null&&timing["firstValidPoseClockMapping"]!=null&&Convert.ToInt64(timing["firstFakeSubmissionProducerFrame"])==0,"first genuine pose mapping and first fake submission clocks retained");if(config.LatencyProfile=="low-latency-01"){Need((bool)final["sourcePreparedForSteadyWindow"]&&Convert.ToInt64(final["startupCreditsRetired"])==2,"genuine source status permits exactly one two-credit retirement");Need(Convert.ToInt64(final["producerStartupBlocks"])==8&&Convert.ToInt64(final["steadyProducerCreditBlocks"])==6,"cold startup and steady window remain separately declared");}var result=new{profile=config.LatencyProfile??"baseline",authoredMainOperatingPoseValues=120,authoredNominalTelemetryHz=20,sourceClock="actual fixture host QPC; authored values, not live GTA",coldStartupToNonzeroStatusMs=startupMs,contentionWorkers=cpuWorkers,logicalProcessors=Environment.ProcessorCount,ownedProcessContentionAffinityMask=cpuWorkers>0?contentionMask:0,affinityRestoredBeforeFade=true,contentionAndHarnessCpuMs=loadCpuMs,contentionWindow="During120 main authored observations only; workers released and joined before fade",measurement=final};current=null;return result;
 }
 static object SafeRun(string candidate){try{return Run(candidate);}catch(Exception error){armFailed=true;var measurement=current==null?null:Read(Path.Combine(root,".local","gameplay",current.Session,"host.json"));return new{profile=PlayableConfiguration.Load(Path.Combine(candidate,"playable.json")).LatencyProfile??"baseline",passed=false,failure=error.ToString(),contentionWorkers=cpuWorkers,logicalProcessors=Environment.ProcessorCount,ownedProcessContentionAffinityMask=contentionMask,measurement=measurement};}finally{StopLoad();if(current!=null){current.Stop();current.Join(10000);current=null;}}}
 public static int Main(string[] args){try{if(args.Length!=4||!int.TryParse(args[3],out cpuWorkers)||cpuWorkers<0||cpuWorkers>4)throw new ArgumentException("fresh baseline package, candidate package, new result file, bounded0..4 CPU workers");var a=SafeRun(args[0]);var b=SafeRun(args[1]);File.WriteAllText(args[2],Json.Serialize(new{passed=!armFailed,checks,baseline=a,candidate=b,endpointOpened=false,newRecording=false,sourceBanksModified=false,physicalLatencyMeasured=false,sameInputScope="Same120 stationary/rev/moving operating and pose values at20Hz; real scheduling and cold starts measured independently, timestamps necessarily differ."}));Console.WriteLine((armFailed?"FAIL ":"PASS ")+checks+" actual Node/ring profile A/B; no endpoint/recording; "+args[2]);return armFailed?1:0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{StopLoad();if(current!=null){current.Stop();current.Join(10000);}}}
}
